import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class PublicExamplesTest{static String capture(Runnable action){PrintStream previous=System.out,oldErr=System.err;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);System.setErr(out);action.run();}finally{System.setOut(previous);System.setErr(oldErr);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void commonPublicFifoAndFailures(){for(int kind=0;kind<3;kind++){Object q=TaskBinding.queue(kind,2);assertEquals("",capture(()->{TaskBinding.put(q,'A');TaskBinding.put(q,'B');}));if(kind<2)assertEquals("Очередь переполнена\n",capture(()->TaskBinding.put(q,'C')));else assertEquals("",capture(()->TaskBinding.put(q,'C')));assertEquals("",capture(()->{assertEquals('A',TaskBinding.get(q));assertEquals('B',TaskBinding.get(q));}));if(kind==2)assertEquals('C',TaskBinding.get(q));assertEquals("Очередь пуста\n",capture(()->assertEquals('\0',TaskBinding.get(q))));}}}
